Does the processor on the device ever run the loops in `make_table()`? What does the `static_assert` check?

```cpp
#include <array>
#include <cstdint>
constexpr std::array<std::uint8_t, 256> make_table() {
    std::array<std::uint8_t, 256> t{};
    for (int i = 0; i < 256; ++i) {
        unsigned c = i;
        for (int b = 0; b < 8; ++b) c = (c & 0x80) ? (c << 1) ^ 0x07 : c << 1;
        t[i] = static_cast<std::uint8_t>(c);
    }
    return t;
}
constexpr auto kTable = make_table();
static_assert(kTable[0x80] == 0x89);
```

