A **`std::span`** is a pointer plus a length that refers to a contiguous run of elements owned by someone else. What does this print?

```cpp
#include <array>
#include <cstdio>
#include <span>
int sum(std::span<const int> v) {
    int s = 0;
    for (int x : v) s += x;
    return s;
}
int main() {
    int raw[3] = {1, 2, 3};
    std::array<int, 5> arr{10, 20, 30, 40, 50};
    std::printf("%d %d %d\n", sum(raw), sum(arr), sum(std::span(arr).subspan(1, 2)));
}
```

A **`std::string_view`** is a pointer plus a length that refers to characters stored elsewhere. What does this print?

```cpp
#include <cstdio>
#include <string_view>
int main() {
    char line[] = "GET /temp HTTP";
    std::string_view v(line);
    std::string_view cmd = v.substr(0, 3);
    std::printf("%zu %.*s\n", cmd.size(), static_cast<int>(cmd.size()), cmd.data());
    line[0] = 'S';
    std::printf("%c\n", cmd[0]);
}
```

A **lambda** is an unnamed function written inline; `[limit]` captures the local `limit` by copy. What does this print?

```cpp
#include <algorithm>
#include <array>
#include <cstdio>
int main() {
    std::array<int, 5> v{40, 10, 30, 20, 50};
    int limit = 25;
    std::sort(v.begin(), v.end(), [](int a, int b) { return a > b; });
    auto it = std::find_if(v.begin(), v.end(), [limit](int x) { return x < limit; });
    std::printf("%d %td\n", *it, it - v.begin());
}
```

This program replaces `operator new` with a version that counts calls. How many heap allocations does it count for the vector, and what does that tell you about `std::vector` on a device with no heap?

```cpp
#include <cstdio>
#include <cstdlib>
#include <vector>
static int g_news = 0;
void* operator new(std::size_t n) { ++g_news; return std::malloc(n); }
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }
int main() {
    std::vector<int> v;
    v.reserve(4);
    for (int i = 0; i < 4; ++i) v.push_back(i);
    std::printf("%d\n", g_news);
}
```

**`std::optional<T>`** holds either a `T` or nothing. What does this print?

```cpp
#include <cstdio>
#include <optional>
std::optional<int> find_index(const int* a, int n, int key) {
    for (int i = 0; i < n; ++i)
        if (a[i] == key) return i;
    return std::nullopt;
}
int main() {
    int a[3] = {5, 6, 7};
    auto r = find_index(a, 3, 7);
    auto s = find_index(a, 3, 9);
    std::printf("%d %d %d\n", r.has_value(), r.value_or(-1), s.value_or(-1));
}
```

**`std::variant<A, B>`** is a type-safe tagged union: it holds exactly one of its alternatives and remembers which. What does this print?

```cpp
#include <cstdio>
#include <variant>
struct Ok  { int value; };
struct Err { int code; };
int main() {
    std::variant<Ok, Err> r = Err{3};
    r = Ok{42};
    if (auto* p = std::get_if<Ok>(&r)) std::printf("ok %d\n", p->value);
    std::printf("%zu\n", r.index());
}
```

